CH = dict(num=3, tag="History", theme="Trade, migration, technology, world wars, Great Depression and the post-war order",
 title="The Making of a Global World",
 intro="Today's world of trade, migration and shared culture has a long history. This chapter looks at the silk routes and the exchange of food and diseases, the nineteenth-century world economy, the shocks of two world wars and the Great Depression, and the rebuilding of the world economy after 1945.",
 big_questions=["How did early trade link the world?", "How did the nineteenth century change trade, labour and technology?", "What did the wars and Depression do to the world economy?", "How did the post-war order, Bretton Woods and decolonisation shape the world?"],
 blocks=[
 ("h2", "The Pre-Modern World"),
 ("ul", ["The **silk routes** linked Asia with Europe and North Africa; they are named for the Chinese silk carried along them. Pottery from China, textiles and spices from India and precious metals from the Americas travelled too, and religions such as Christianity and Islam spread along trade routes.", "Food travelled: noodles, according to one story, from China to the West and became spaghetti; ordinary foods like potatoes, soya, groundnuts, maize, tomatoes, chillies and sweet potatoes came from the Americas after **Columbus** (1492) discovered the continent. The potato helped Europe's poor eat better and live longer, but in Ireland the failure of the potato crop (1845-49) led to a terrible famine.", "The **conquest of the Americas** was helped by disease: European germs such as smallpox killed vast numbers of native people who had no immunity. Silver from mines in Peru and Mexico enriched Europe and financed trade with Asia."]),
 ("h2", "The Nineteenth Century (1815-1914)"),
 ("p", "The world economy changed because of shifts in food supply, labour, capital and technology."),
 ("table", ["Area", "Change"], [["Food and population", "Britain's population grew, so food prices rose; after the Corn Laws (restricting grain imports) were abolished in 1846 cheap food from America, Russia and Australia flowed in. Landowners lost out; people moved to cities."], ["Labour", "Migration from Europe to America and Australia; about 50 million migrated from Europe in the nineteenth century, and many more from India and China."], ["Capital", "British and other European capital financed railways, ports and plantations."], ["Technology", "Railways, steamships and the telegraph linked markets; refrigerated ships carried meat."]]),
 ("h3", "Colonies and trade"),
 ("ul", ["**Africa:** At the Berlin Conference of **1885** European powers divided Africa among themselves. In the **1890s** **rinderpest**, a fast-spreading cattle disease, arrived in Africa and killed about 90 per cent of cattle; this loss of livelihood forced Africans to work for wages for European mining and plantation owners, and helped colonisers conquer the continent.", "**Indentured labour:** Many Indian and Chinese workers worked on plantations and mines in the Caribbean, Fiji, Mauritius and Africa under contracts called **indentures**. Most were from eastern UP, Bihar, central India and dry districts of Tamil Nadu. Recruiters often misled them about the work and the journey; conditions were harsh. The system was abolished in **1921**. Some cultural forms emerged, such as *Hosay* in Trinidad, *chutney music* and the Rastafari movement.", "**Indian trade:** Before 1800 Indian cotton textiles dominated world trade. After the Industrial Revolution Britain stopped imports and flooded India with machine goods. Indian exports shifted to raw materials: raw cotton, indigo, opium and wheat. Britain had a trade surplus with India, which it used to settle its deficits with other countries and to pay ‘home charges’ (pensions and debts) owed by the colonial government. Indian traders and moneylenders, such as the **Shikaripuri shroffs** and **Nattukottai Chettiars**, financed agricultural export crops in Central and South-East Asia."]),
 ("h2", "The Inter-War Economy"),
 ("ul", ["The **First World War (1914-18)** was fought between the Allies (Britain, France, Russia and later the US) and the Central Powers (Germany, Austria-Hungary, Ottoman Empire). Millions died; the war changed Britain from an international creditor into a debtor, and the USA became the leading creditor.", "After the war, Britain struggled to regain its Indian market because of Japanese competition. Wartime industries had to be shut down or cut, leading to unemployment.", "**Mass production and consumption** grew in the US: Henry Ford's moving **assembly line** made cars cheap; American consumer goods such as refrigerators, washing machines, radios and gramophones were bought on credit; housing and car booms followed. This prosperity ended in the late 1920s."]),
 ("note", "IMPORTANT", "**The Great Depression (1929 onwards).** Causes: agricultural overproduction led to falling prices and farmers' incomes; US loans to Europe stopped in the mid-1920s; and the **Wall Street crash of 29 October 1929** collapsed the banking system, with thousands of banks closing. Unemployment peaked in the early 1930s at about a quarter of workers in the US. World trade fell by about half between 1929 and 1932."),
 ("ul", ["**India** was badly affected: exports and imports nearly halved between 1928 and 1934; prices of wheat fell by 50 per cent; farmers' debts rose. Jute producers in Bengal were hard hit. Urban dwellers with fixed incomes gained from falling prices. India also became an exporter of gold during the 1930s, which helped Britain.", "Peasants who produced cash crops suffered most, and their anger fed the Civil Disobedience Movement of 1930."]),
 ("h2", "Rebuilding a World Economy after 1945"),
 ("ul", ["The **Second World War (1939-45)** killed vast numbers; economists and politicians learnt two lessons: an industrial society needs mass consumption and so high incomes, and full employment should be a goal of government.", "In **July 1944**, an international conference at **Bretton Woods (New Hampshire, USA)** set up the **International Monetary Fund (IMF)** to deal with external surpluses and deficits and the **World Bank (International Bank for Reconstruction and Development)** to finance post-war reconstruction. The IMF and World Bank started financial operations in **1947**. They are called the **Bretton Woods institutions**; the system was based on fixed exchange rates, with the US dollar linked to gold.", "Decolonisation: many Asian and African countries became independent but were poor, with weak economies; the IMF and the World Bank did not at first focus on them. Developing countries organised themselves as the **Group of 77 (G-77)** and demanded a **New International Economic Order (NIEO)** to give control over their natural resources and fairer trade terms.", "Fixed exchange rates ended in the early **1970s**, and floating rates took over. Oil price shocks of **1973** hit the industrial world; MNCs moved production to low-wage countries, e.g. in Asia; China opened its economy in 1978; the collapse of the Soviet Union and Eastern Europe in the 1990s brought those countries into the world economy."]),
 ("table", ["Period", "Key feature"], [["1500s", "Columbus' voyages, exchange of foods and diseases"], ["1815-1914", "Free trade, migration, colonial conquest"], ["1914-1945", "Wars, mass production, Great Depression"], ["1944-1970s", "Bretton Woods, fixed exchange rates, decolonisation"], ["After 1970s", "Floating rates, MNCs, globalisation"]]),
 ("h2", "Quick Revision: Likely Exam Questions"),
 ("qa", [
  ("What were the silk routes?", "Trade and cultural routes linking Asia, Europe and Africa."),
  ("Why did rinderpest change Africa?", "It killed most cattle, forcing people to take wage work and easing colonial conquest."),
  ("What was indentured labour?", "Contract labour under which workers were bound for a fixed term, often in poor conditions; abolished 1921."),
  ("What caused the Great Depression?", "Overproduction, falling prices, withdrawal of US loans and the 1929 stock crash."),
  ("What was Bretton Woods?", "1944 conference creating the IMF and World Bank."),
  ("What was NIEO?", "Demand by G-77 developing countries for control over resources and fairer trade."),
  ("How did the Depression affect India?", "Exports and prices fell, farmers fell into debt, and jute and wheat growers suffered."),
 ]),
 ],
 takeaways=["Trade, food and diseases linked distant regions long before modern globalisation.", "In the **nineteenth century** trade grew, with migration, **indentured labour** and colonial control.", "The wars, mass production and the **Great Depression of 1929** shook the world economy.", "**Bretton Woods (1944)** created the **IMF and World Bank**; decolonisation gave rise to the G-77 and the NIEO demand.", "After the 1970s, floating exchange rates and multinational companies paved the way for today's globalisation."])
